const { env } = await import('node:process');
if (!env.INPUT_PATH) throw new Error('Missing INPUT_PATH env var');
globalThis.inputPath = env.INPUT_PATH;

const fs = await import('node:fs');
const { readFileSync } = fs;
const tomlPkg = await import('@iarna/toml');
const { parse } = tomlPkg.default || tomlPkg;
const content = readFileSync(globalThis.inputPath, 'utf8');
const obj = parse(content);
globalThis.resultJson = JSON.stringify(obj);
